import { defineRelations, defineRelationsPart } from "drizzle-orm";
import {
  pgTable,
  text,
  timestamp,
  boolean,
  index,
  uuid,
} from "drizzle-orm/pg-core";
import { createInsertSchema, createSelectSchema } from "drizzle-orm/zod";
import * as z from "zod";

// <-- Authentication -->
// Generated by Better Auth
export const user = pgTable("user", {
  id: text("id").primaryKey(),
  name: text("name").notNull(),
  email: text("email").notNull().unique(),
  emailVerified: boolean("email_verified").default(false).notNull(),
  image: text("image"),
  createdAt: timestamp("created_at").defaultNow().notNull(),
  updatedAt: timestamp("updated_at")
    .defaultNow()
    .$onUpdate(() => /* @__PURE__ */ new Date())
    .notNull(),
});

export const session = pgTable(
  "session",
  {
    id: text("id").primaryKey(),
    expiresAt: timestamp("expires_at").notNull(),
    token: text("token").notNull().unique(),
    createdAt: timestamp("created_at").defaultNow().notNull(),
    updatedAt: timestamp("updated_at")
      .$onUpdate(() => /* @__PURE__ */ new Date())
      .notNull(),
    ipAddress: text("ip_address"),
    userAgent: text("user_agent"),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
  },
  (table) => [index("session_userId_idx").on(table.userId)],
);

export const account = pgTable(
  "account",
  {
    id: text("id").primaryKey(),
    accountId: text("account_id").notNull(),
    providerId: text("provider_id").notNull(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    accessToken: text("access_token"),
    refreshToken: text("refresh_token"),
    idToken: text("id_token"),
    accessTokenExpiresAt: timestamp("access_token_expires_at"),
    refreshTokenExpiresAt: timestamp("refresh_token_expires_at"),
    scope: text("scope"),
    password: text("password"),
    createdAt: timestamp("created_at").defaultNow().notNull(),
    updatedAt: timestamp("updated_at")
      .$onUpdate(() => /* @__PURE__ */ new Date())
      .notNull(),
  },
  (table) => [index("account_userId_idx").on(table.userId)],
);

export const verification = pgTable(
  "verification",
  {
    id: text("id").primaryKey(),
    identifier: text("identifier").notNull(),
    value: text("value").notNull(),
    expiresAt: timestamp("expires_at").notNull(),
    createdAt: timestamp("created_at").defaultNow().notNull(),
    updatedAt: timestamp("updated_at")
      .defaultNow()
      .$onUpdate(() => /* @__PURE__ */ new Date())
      .notNull(),
  },
  (table) => [index("verification_identifier_idx").on(table.identifier)],
);

// <-- About Me --- Gear -->
export const camera = pgTable("camera", {
  id: text("id").primaryKey(),
  name: text("name").notNull(),
  shortDescription: text("short_description"),
  description: text("description"),
  createdAt: timestamp("created_at").defaultNow().notNull(),
  updatedAt: timestamp("updated_at")
    .defaultNow()
    .$onUpdate(() => /* @__PURE__ */ new Date())
    .notNull(),
});
export const cameraSelectSchema = createSelectSchema(camera);
export const cameraInsertSchema = createInsertSchema(camera);

export const hardwareItem = pgTable("hardware_item", {
  id: text("id").primaryKey(),
  name: text("name").notNull(),
  purpose: text("purpose").notNull(),
  link: text("link"),
});
export const hardwareItemSelectSchema = createSelectSchema(hardwareItem);
export const hardwareItemInsertSchema = createInsertSchema(hardwareItem);
export type HardwareItem = z.infer<typeof hardwareItemSelectSchema>;
export type NewHardwareItem = z.infer<typeof hardwareItemInsertSchema>;

export const softwareItem = pgTable("software_item", {
  id: text("id").primaryKey(),
  name: text("name").notNull(),
  purpose: text("purpose").notNull(),
  description: text("description"),
  link: text("link"),
  disclosureMessageId: uuid("disclosure").references(
    () => disclosureMessage.id,
  ),
});
export const softwareItemSelectSchema = createSelectSchema(softwareItem);
export const softwareItemInsertSchema = createInsertSchema(softwareItem);
export type SoftwareItem = z.infer<typeof softwareItemSelectSchema>;
export type NewSoftwareItem = z.infer<typeof softwareItemInsertSchema>;

export const disclosureMessage = pgTable("disclosure_message", {
  id: uuid("id").defaultRandom().primaryKey(),
  message: text("message").notNull(),
  link: text("link").notNull(),
});
export const disclosureMessageSelectSchema =
  createSelectSchema(disclosureMessage);
export const disclosureMessageInsertSchema =
  createInsertSchema(disclosureMessage);

// <-- Relations -->
export const schema = {
  user,
  session,
  account,
  verification,
  camera,
  hardwareItem,
  softwareItem,
  disclosureMessage,
} as const;
